'use strict';
const fs=require('node:fs'),path=require('node:path'),readline=require('node:readline'),crypto=require('node:crypto'),assert=require('node:assert/strict'),z=require('node:zlib');
const R=path.resolve(__dirname,'..'),D=path.join(R,'reports/ai-foundation-20261119'),read=p=>JSON.parse(fs.readFileSync(path.join(R,p))),audit=read('reports/ai-foundation-20261119/original20-income-development-audit-20261119-v1.json'),old=read('reports/ai-foundation-20261119/v486-random20-runtime-preflight-20261119-v1.json').runtime,current=JSON.parse(fs.readFileSync('/private/tmp/seti-final-currency-20261119.json')).runtime,out=path.join(D,'early-technology-usage-audit-20261119-v1.json');
if(fs.existsSync(out)&&JSON.parse(fs.readFileSync(out)).status==='complete'){console.log('Reuse completed technology audit');process.exit();}
const report=fs.existsSync(out)?JSON.parse(fs.readFileSync(out)):{status:'running',newAISearches:0,newGames:0,sourcePolicy:audit.sourcePolicy,forecast:{computerCyclesPerLaterRound:1,usefulScansPerLaterRound:4},boards:[]},persist=()=>fs.writeFileSync(out,JSON.stringify(report,null,2)+'\n');
async function scan(record,runtime){let n=0;const stream=fs.createReadStream(path.join(runtime,record.agentTracePath)),h=crypto.createHash('sha256');stream.on('data',b=>h.update(b));const rounds=Array.from({length:4},(_,i)=>({round:i+1,scanActions:0,scan4Menus:0,scan4Launch:0,scan4Move:0,scan4Skip:0})),research=[];
 for await(const line of readline.createInterface({input:stream,crlfDelay:Infinity})){n++;const row=JSON.parse(line),c=row.context;if(c?.seatId!=='player-white')continue;const p=c.observation.publicState.players.find(p=>p.playerId==='player-white'),round=c.observation.publicState.roundNumber,a=c.legalActions.find(a=>a.actionId===row.actionId);if(!a)continue;const t=a.target||{},r=rounds[round-1];if(a.family==='scan')r.scanActions++;if(t.choiceId?.startsWith('scan4:')){r.scan4Menus++;const field={launch:'scan4Launch',move:'scan4Move',skip:'scan4Skip'}[t.mode];assert(field,'Unknown scan4 mode '+t.mode);r[field]++;}
 if(t.tileId&&t.choiceId?.startsWith('tech:'))research.push({line:n,round,tileId:t.tileId,blueSlot:t.blueSlot,wallet:Object.fromEntries(['credits','energy','publicity','availableData'].map(k=>[k,p[k]])),computer:p.dataProgress,hand:c.observation.selfState.hand.map(c=>c.cardId)});
 if(record.seed==='seti-analyze-421f46598209'&&n===1){const s=row.search,values=[];for(const l of s.lines||[])for(const e of l.edges||[]){const g=e.resourcePlan?.goal;if(g?.kind==='research_tech'){const endpoint=s.lines.find(x=>x.node===e.target);values.push({tileId:g.tileId,blueSlot:g.blueSlot,value:endpoint?.value,completion:endpoint?.completion,boundary:endpoint?.boundary});}}report.selectedCase={board:6,record:record.name,traceLine:1,traceSha256:null,sourceValue:s.value,sourceAction:row.actionId,researchValues:values};const target=path.join(D,'early-technology-board6-source-20261119-v1.json.gz');if(!fs.existsSync(target))fs.writeFileSync(target,z.gzipSync(JSON.stringify({context:c,search:s,actionId:row.actionId})));}
 }return{rounds,research,traceLines:n,traceSha256:h.digest('hex')};}
(async()=>{persist();for(const entry of audit.records){if(report.boards.some(b=>b.board===entry.board))continue;const record=read(entry.record),row=await scan(record,old);assert.equal(row.traceSha256,entry.traceSha256);report.boards.push({board:entry.board,record:entry.record,score:entry.score,...row});if(entry.board===6){report.selectedCase.record=entry.record;report.selectedCase.traceSha256=row.traceSha256;report.selectedCase.actualOpeningInputs=record.steps-row.traceLines;}persist();}
 const teaching=read('reports/research/327c52b2.e08665e6.full.json');report.teachingReference={record:'reports/research/327c52b2.e08665e6.full.json',scope:'autonomous272, not the human405',...await scan(teaching,current)};
 report.summary={meanScansByRound:roundMeans('scanActions'),meanScan4SelectionsByRound:[1,2,3,4].map(r=>report.boards.reduce((n,b)=>n+b.rounds[r-1].scan4Launch+b.rounds[r-1].scan4Move,0)/20),meanScan4SkipsByRound:roundMeans('scan4Skip'),earlyPurple4Boards:report.boards.filter(b=>b.research.some(r=>r.round===1&&r.tileId==='purple4')).length,limitations:['Selected scan4 launch/move counts are observed use, not a causal value or resource-saving estimate.','Observed low activity can itself be a result of policy; this audit alone does not justify lowering a forecast.','Original20 use old v486; no V72 cohort retest.']};report.status='complete';persist();console.log(JSON.stringify({summary:report.summary,selectedCase:report.selectedCase,teachingRounds:report.teachingReference.rounds}));
 function roundMeans(key){return[1,2,3,4].map(r=>report.boards.reduce((n,b)=>n+b.rounds[r-1][key],0)/20);}
})().catch(e=>{report.status='failed';report.failure={message:e.message,stack:e.stack};persist();console.error(e.stack);process.exitCode=1;});
